import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { checkFollowUsers } from "../handlers/checkFollowUsers";
import type { ApiError } from "../runtime/client";
import type { CheckFollowUsersRequest } from "../types/CheckFollowUsersRequest";
import type { SpacePartition } from "../types/SpacePartition";

type Data = Awaited<ReturnType<typeof checkFollowUsers>>;
type Vars = { spaceId: SpacePartition; req: CheckFollowUsersRequest };

export function useCheckFollowUsers(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => checkFollowUsers(vars.spaceId, vars.req),
    ...options,
  });
}
